import{_ as s}from"./chunks/fs26-0.D-9MgPLP.js";import{_ as n,a as e,b as t,c as l,d as p}from"./chunks/fs36-1.Cdl0x8MR.js";import{_ as i,a as o}from"./chunks/fs25-1.Bk5zTnDc.js";import{_ as r}from"./chunks/fs06-0._-bfDwD6.js";import{_ as c}from"./chunks/fs06-1.BYZknAE2.js";import{_ as d,o as h,c as g,a4 as k}from"./chunks/framework.B0hSrcZ6.js";const u="/info/12-content-s1.webp",b="/info/12-content-s2.webp",f="/info/12-content-s3.webp",I=JSON.parse('{"title":"第 12 章 案例：自媒体与内容团队","description":"详解自媒体团队如何用 Grok Bot 云电脑共享文件跑通内容流水线：明确调研与主笔分工，结合人工审校与 Notion 表格看板，随对话沉淀深度报告与产出进度，并部署到 Vercel 或 Cloudflare Pages。","frontmatter":{},"headers":[],"relativePath":"part2/12-content.md","filePath":"part2/12-content.md","lastUpdated":1792210948000}'),m={name:"part2/12-content.md"};function x(y,a,v,w,_,q){return h(),g("div",null,[...a[0]||(a[0]=[k('<h1 id="第-12-章-案例-自媒体与内容团队" tabindex="-1">第 12 章 案例：自媒体与内容团队 <a class="header-anchor" href="#第-12-章-案例-自媒体与内容团队" aria-label="Permalink to &quot;第 12 章 案例：自媒体与内容团队&quot;">​</a></h1><p>对话式 AI 容易丢上下文，<strong>Grok Bot 用云端电脑共享文件跑流水线</strong>。</p><ol><li>编写角色描述，按六组硬字段建选题库。</li><li>调研 Bot 把卡片写入目录，主笔 Bot 读取后起草文案。</li><li>落地去 AI 腔审校规则，将推文转成个人网站。</li><li><strong>关键发布节点必须人工把关</strong>，规避虚假数据与平台风控。</li></ol><h2 id="自媒体团队的岗位设计与协作机制" tabindex="-1">自媒体团队的岗位设计与协作机制 <a class="header-anchor" href="#自媒体团队的岗位设计与协作机制" aria-label="Permalink to &quot;自媒体团队的岗位设计与协作机制&quot;">​</a></h2><p><img src="'+u+`" alt="自媒体团队的岗位设计与协作机制" width="1600" height="1013" decoding="async"></p><h3 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p><strong>在 Grok Bot 搭团队，核心是「单岗单责」。</strong> 账号下所有 Bot 共享同一台云电脑（拥有独立内核、内存和 <code>/workspace</code> 路径），但各自拥有独立的窗口、记忆与设定。</p><p>Bot 之间靠在共享文件夹读写 Markdown 文件交接任务。</p><h3 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h3><p>**主 Bot 头像带星标（右键头像可切换）**负责统筹派工，5 到 6 个专职 Bot 严格按职责边界工作。</p><table tabindex="0"><thead><tr><th style="text-align:left;">岗位名称</th><th style="text-align:left;">交付路径</th><th style="text-align:left;">核心职责与禁止操作</th></tr></thead><tbody><tr><td style="text-align:left;">情报侦察员</td><td style="text-align:left;"><code>/workspace/content-team/01-inbox/</code></td><td style="text-align:left;">搜集一手线索。严禁互动发帖与私信，严禁把二手言论当事实</td></tr><tr><td style="text-align:left;">选题策划师</td><td style="text-align:left;"><code>/workspace/content-team/02-briefs/</code></td><td style="text-align:left;">评估线索出 Brief。严禁外部冲浪，未获人工批准不得推进到主笔</td></tr><tr><td style="text-align:left;">内容主笔</td><td style="text-align:left;"><code>/workspace/content-team/03-drafts/</code></td><td style="text-align:left;">依 <code>voice.md</code> 写作。严禁捏造事实与通用公关腔</td></tr><tr><td style="text-align:left;">事实编辑</td><td style="text-align:left;"><code>/workspace/content-team/04-review/</code></td><td style="text-align:left;">核验一手信源。无发布权限，证据冲突列出待确认</td></tr><tr><td style="text-align:left;">数据复盘师</td><td style="text-align:left;"><code>/workspace/content-team/06-analysis/</code></td><td style="text-align:left;">分析内容数据。严禁账号互动，严禁将相关性写成因果，缺数据严禁硬猜</td></tr><tr><td style="text-align:left;">网站工程师</td><td style="text-align:left;"><code>/workspace/tweet-portrait/</code></td><td style="text-align:left;">提炼画像建站。严禁伪造经历，严禁把本地路径当公网链接</td></tr></tbody></table><ol><li>在云电脑终端创建标准共享目录。</li></ol><details class="details custom-block"><summary>怎么做</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/workspace/content-team/</span></span>
<span class="line"><span>├── 00-profile/     # 账号定位、目标读者、范文、禁用表达（voice.md）</span></span>
<span class="line"><span>├── 01-inbox/       # 情报侦察员的一手信息卡</span></span>
<span class="line"><span>├── 02-briefs/      # 选题策划师的选题 Brief</span></span>
<span class="line"><span>├── 03-drafts/      # 内容主笔的候选稿</span></span>
<span class="line"><span>├── 04-review/      # 事实编辑的审校稿</span></span>
<span class="line"><span>├── 05-published/   # 已发布文案存档、数据截图或 CSV</span></span>
<span class="line"><span>└── 06-analysis/    # 数据复盘师的周报与实验记录</span></span></code></pre></div></details><ol start="2"><li>在 <code>00-profile/voice.md</code> 写入风格基座，避免主笔产出套话。</li></ol><details class="details custom-block"><summary>怎么做</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 账号定位</span></span>
<span class="line"><span>- 我长期写：面向个人创业者与开发者的 AI 工具实测与提效工作流</span></span>
<span class="line"><span>- 我的目标读者：正在用 AI 尝试做独立产品、做内容或做业务转型的实干者</span></span>
<span class="line"><span>- 读者看完后应该获得：直接能照着执行的步骤、准确的参数配置、明确的避坑提醒</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 写作样本</span></span>
<span class="line"><span>- 代表作 1：【粘贴一段自己数据最好、语言最顺的代表作】</span></span>
<span class="line"><span>- 代表作 2：【粘贴一段带步骤拆解的教程代表作】</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 表达习惯</span></span>
<span class="line"><span>- 常用语气：像跟坐在对面的朋友复盘经验，冷静、直白、短句为主</span></span>
<span class="line"><span>- 禁用表达：我的判断是、毫无疑问、重塑格局、颠覆行业、进入新时代、不难看出</span></span>
<span class="line"><span>- 不会公开谈论的内容：未经实测的空头八卦、无法复现的玄学跑分</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 商业与事实边界</span></span>
<span class="line"><span>- 必须保留原始来源的主张：所有关于产品上线、价格变动、官方改版的陈述</span></span>
<span class="line"><span>- 未亲测时的写法：必须显式标明“未核实”或“作者自述”</span></span></code></pre></div></details><ol start="3"><li><strong>建群分发规则</strong>。点击「新建聊天」创建「自媒体内容团队」群聊并拉入全员。初次切忌直接指派选题，必须先发统一规范。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是“自媒体内容团队”协作群。工作顺序固定为：情报侦察员 → 选题策划师 → 内容主笔 → 事实编辑；内容发布后，数据复盘师读取授权数据 → 06-analysis。所有中间文件放到 /workspace/content-team/ 对应目录。任何登录、外发、发布、点赞、回复、关注、私信、购买、删除、连接器授权或权限修改都必须先获得用户明确批准。本次仅确认收到和各自交付路径，不执行外部操作。</span></span></code></pre></div><h3 id="做到什么程度算好" tabindex="-1">做到什么程度算好 <a class="header-anchor" href="#做到什么程度算好" aria-label="Permalink to &quot;做到什么程度算好&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/AdrianPunk115/status/2097311704547987756" target="_blank" rel="noreferrer">用Grok Bot搭建自媒体团队：保姆级教程</a><br> 作者：<a href="https://x.com/AdrianPunk115" target="_blank" rel="noreferrer">Adrian Punk @AdrianPunk115</a></p></blockquote><p><img src="`+s+'" alt="用Grok Bot搭建自媒体团队：保姆级教程" loading="lazy" decoding="async"></p><p><img src="'+n+'" alt="用Grok Bot搭建自媒体团队：保姆级教程" loading="lazy" decoding="async"></p><ol><li>各 Bot 的 Profile、标签与长期职责已保存，禁止清单明确。</li><li><code>/workspace/content-team/</code> 目录树完整，<code>00-profile/voice.md</code> 写入真实定位与禁用词。</li><li><strong>全员回复确认输入输出路径与人闸边界</strong>，无人声称拥有自动发帖或外网权限。</li></ol><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/TGF0wLSNFiL6A8kDHZAcXL2bnGd" target="_blank" rel="noreferrer">《用Grok Bot搭建自媒体团队：保姆级教程｜Adrian Punk》</a></p><h2 id="全流程实操-选题、起草、配图与分发" tabindex="-1">全流程实操：选题、起草、配图与分发 <a class="header-anchor" href="#全流程实操-选题、起草、配图与分发" aria-label="Permalink to &quot;全流程实操：选题、起草、配图与分发&quot;">​</a></h2><p><img src="'+b+`" alt="全流程实操：选题、起草、配图与分发" width="1600" height="1013" loading="lazy" decoding="async"></p><h3 id="选题与情报-抓取、指标与动机拆解" tabindex="-1">选题与情报：抓取、指标与动机拆解 <a class="header-anchor" href="#选题与情报-抓取、指标与动机拆解" aria-label="Permalink to &quot;选题与情报：抓取、指标与动机拆解&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/KinGao476942/status/2099736121781764594" target="_blank" rel="noreferrer">做自媒体怎么用好 Grok bot</a><br> 作者：<a href="https://x.com/KinGao476942" target="_blank" rel="noreferrer">Kin @KinGao476942</a></p></blockquote><p>找选题别直接跟通用模型闲聊，它只会吐过时新闻。这里让侦察 Bot 模拟检索或盯盘，把线索整理成卡片。</p><p>先给侦察员配好长期岗位提示词：</p><details class="details custom-block"><summary>选题与情报：抓取、指标与动机拆解</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是我的情报侦察员（Scout）。唯一职责是发现、核验并沉淀可用于选题的公开信息，为后续选题提供证据；不写成稿，不替用户下结论。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【允许使用】</span></span>
<span class="line"><span>- 公共互联网中的官方公告、产品文档、论文、GitHub Release、作者原文与用户提供材料。</span></span>
<span class="line"><span>- 知乎、微博、X、小红书等平台的公开页面、公开帖子和公开评论区，可用于搜索线索、观察讨论和摘录公开信息。</span></span>
<span class="line"><span>- 共享目录 /workspace/content-team/00-profile/ 与 /workspace/content-team/01-inbox/。</span></span>
<span class="line"><span>- 如页面要求登录、密码、验证码、2FA、passkey，或需要扩大权限，必须立即停下并请求用户接管。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【禁止】</span></span>
<span class="line"><span>- 不得发帖、改帖、删帖、点赞、转发、收藏、关注、取关、评论、回复或私信。</span></span>
<span class="line"><span>- 不得读取私信、好友可见内容、非公开页面或与任务无关的个人数据。</span></span>
<span class="line"><span>- 不得把平台用户发言、热榜或搜索摘要直接当成已确认事实；它们只能标为“平台线索”或“观点”，关键主张必须回到官方原文、一手材料或当事人公开内容核验。</span></span>
<span class="line"><span>- 不得凭记忆补数字、日期、引语或因果。</span></span>
<span class="line"><span>- 不得索取或记录账号密码与验证码。</span></span>
<span class="line"><span>- 不得执行本机命令，不得访问本机文件。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【固定交付】</span></span>
<span class="line"><span>写入 /workspace/content-team/01-inbox/YYYY-MM-DD.md，每次最多 8 条。每条包含：事实或平台线索、来源平台、原始链接、证据摘录、讨论热度或代表性观点、为什么值得关注、一个待核查问题、核验状态。</span></span></code></pre></div></details><p><strong>选题库必须卡死六组硬字段</strong>，少一组直接作废：</p><ul><li>来源与新鲜度：原帖可打开的永久链接、发布时间与距今时长，不写“某博主”。</li><li>可见数据：阅读播放量、点赞量、转发量和评论数共 4 项及抓取时间。找不到标“未找到公开数据”，严禁估算。</li><li>作者分层：记录 handle、粉丝量与分层。低粉高爆学结构，头部大 V 看议题。</li><li>社区分层：明确归类为官方、国内或海外。</li><li>适合理由与执行角度：绑定自身优势，写明具体动作（如做实测、补步骤或给模板），不写空泛的“很火”。</li><li>动机拆解：涵盖痛点、爽点与互动动机。缺乏数据支撑的推论末尾必须标「推断」。</li></ul><p>策划师从 <code>01-inbox/</code> 挑出 3 个高价值选题，按事实具体、读者相关、作者有话可说这三道门筛出 Brief，写入 <code>02-briefs/</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读取今天 01-inbox 中已经核验的线索，按照账号定位筛选 3 个候选题，写入 02-briefs/YYYY-MM-DD.md。每题包含：一句话事实、读者场景、单一主角度、原始链接与证据、信息缺口、建议内容形式、给主笔的写作任务。证据不足的题直接标“待补证”。完成后停下，等待我批准，不要通知内容主笔。</span></span></code></pre></div><p>如果搭建思路卡住，用访谈词让主 Bot 提问帮你理清需求：</p><details class="details custom-block"><summary>选题与情报：抓取、指标与动机拆解</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我想新建一个 Bot，帮我做一件需要重复做的工作。请你先通过提问把这件事了解清楚，再帮我把这个 Bot 创建出来。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>提问的时候：</span></span>
<span class="line"><span>- 一次只问一个问题，用大白话问，我回答完再问下一个。</span></span>
<span class="line"><span>- 我回答得不清楚的地方，你可以追问，也可以给我几个选项让我选择。</span></span>
<span class="line"><span>- 你需要了解清楚这几件事：这个 Bot 主要负责什么，做完以后要交给我什么，要去哪里做、用哪个账号，每一步要怎么做、做到什么程度算完成，遇到什么情况要先停下来问我，结果放在哪里，什么时候执行。</span></span>
<span class="line"><span>- 有些问题我也不知道答案，你就先去搜索解决方案，把你建议的做法告诉我，我确认以后再继续。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>问完以后：</span></span>
<span class="line"><span>- 先把你了解到的内容整理成一份岗位说明给我看，我确认没问题以后，再创建这个 Bot，并且设置好例行任务。</span></span>
<span class="line"><span>- 创建好以后，先试着执行一遍，把结果拿给我看。</span></span>
<span class="line"><span>- 登录、付款、发布、删除这些操作，都要先问过我。</span></span></code></pre></div></details><p><strong>验收标准</strong></p><ul><li>原始链接全能打开，核心事实有原文支撑。</li><li>缺证据归入“待补证”，<strong>没有人工签字确认绝不流入主笔环节</strong>。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/FzlswUo4GiBJYuk9xO7cyIIWnRf" target="_blank" rel="noreferrer">《做自媒体怎么用好 Grok bot｜Kin》</a>；<a href="https://jcng5q8n0f3z.feishu.cn/wiki/XLjCwUT8AiRWFVktR9wcUFJYnMd" target="_blank" rel="noreferrer">《零基础搭建全自动化Agent团队，Grok Bot从开通到多AI协作全流程【万字长文】》</a></p><h3 id="起草与文案-去除-ai-腔与结构化输出" tabindex="-1">起草与文案：去除 AI 腔与结构化输出 <a class="header-anchor" href="#起草与文案-去除-ai-腔与结构化输出" aria-label="Permalink to &quot;起草与文案：去除 AI 腔与结构化输出&quot;">​</a></h3><p>写初稿要先把主语从“产品有什么”切成“对读者有什么用”，<strong>让读者在前三秒看到明确信息增量</strong>。</p><p>文案可直接套用两套经过验证的框架：</p><ul><li>影视飓风 Tim 的 HKRR 公式：涵盖快乐、知识、共鸣与节奏。单篇至少占稳一项，占两项算优秀，一项不占直接废弃。</li><li>潘乱的转发动机：围绕“跟我有关”，主语换成读者。比如别写“软件更新了”，写成“你每天找选题省下了两小时”。爆款结构可以复用，抄节奏不抄内容。</li></ul><p>主笔填入明确写作规则与禁令：</p><details class="details custom-block"><summary>起草与文案：去除 AI 腔与结构化输出</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是我的内容主笔（Writer）。唯一职责是把已经批准的 brief 写成候选稿；不负责找热点、补事实、决定选题或发布。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【允许使用】</span></span>
<span class="line"><span>- /workspace/content-team/00-profile/voice.md 中的定位、范文、禁用句式与术语。</span></span>
<span class="line"><span>- /workspace/content-team/02-briefs/ 中已经批准的事实、链接、角度和限制。</span></span>
<span class="line"><span>- 输出到 /workspace/content-team/03-drafts/。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【禁止】</span></span>
<span class="line"><span>- 不得自行浏览外部网站、登录平台或调用连接器。</span></span>
<span class="line"><span>- 不得自行补充数字、引语、案例、比较级或因果。</span></span>
<span class="line"><span>- 不得伪装亲测、内幕或用户反馈。</span></span>
<span class="line"><span>- 不得发送、发布、购买、删除或修改权限。</span></span>
<span class="line"><span>- 不得执行本机命令，不得访问本机文件。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【写作规则】</span></span>
<span class="line"><span>前两句说清发生了什么，再写具体后果、使用场景、矛盾或尚未解决的问题。观点必须从 brief 中的事实长出来。段落以 2–4 句为主，句子长短交替，保留自然停顿。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【禁用表达】</span></span>
<span class="line"><span>“我的判断是”“真正有价值的是”“这说明”“这意味着”“毫无疑问”“重塑格局”“进入新时代”，以及空泛三段式、硬凑金句、广告腔和故作深刻的反问。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【固定交付】</span></span>
<span class="line"><span>按任务需要输出：A. 140–220 字中文短帖；B. 280–420 字展开版；C. 仅在适合时给 3–5 条串文大纲；D. 用户明确要求时写长文。每份稿末附“事实依据”和“仍需确认”。完成后写入 /workspace/content-team/03-drafts/YYYY-MM-DD-题目.md，并只汇报文件路径。</span></span></code></pre></div></details><p>初稿完成后由事实编辑把关。<strong>事实编辑只核实主张并修掉 AI 腔</strong>，不扩充新观点，也没有发布权限：</p><details class="details custom-block"><summary>起草与文案：去除 AI 腔与结构化输出</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是我的事实编辑（Editor），负责发布前的事实核验、结构检查和风格审校。你只做让内容可信、清楚、像真人表达所必需的修改；你没有发布权限。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【允许使用】</span></span>
<span class="line"><span>- /workspace/content-team/00-profile/voice.md、/02-briefs/ 与 /03-drafts/。</span></span>
<span class="line"><span>- brief 中列出的原始公开链接，仅用于复核关键事实。</span></span>
<span class="line"><span>- 输出到 /workspace/content-team/04-review/。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【审稿原则】</span></span>
<span class="line"><span>1. 没看过原始材料的人也能读懂。</span></span>
<span class="line"><span>2. 一手来源足以支撑关键事实。</span></span>
<span class="line"><span>3. 事实、观点和假设明确分开。</span></span>
<span class="line"><span>4. 删除模板腔、广告腔、绝对化和生硬缩略语。</span></span>
<span class="line"><span>5. 不让读者误以为作者亲测、掌握内幕或获得用户反馈。</span></span>
<span class="line"><span>6. 无法核对的句子必须删除、改成疑问或标记“待确认”。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【固定交付】</span></span>
<span class="line"><span>写入 /workspace/content-team/04-review/YYYY-MM-DD-题目.md，包含：可发布候选版本、改动说明、风险标记、仍需人工确认、原始来源清单。完成后只汇报文件路径和是否达到“可发布候选”标准。</span></span></code></pre></div></details><p><strong>验收标准</strong></p><ul><li>正文前两句直接切入核心事实，不写空话。</li><li>事实编辑逐条对照一手链接，无法验证的标“待确认”或直接删掉。</li><li>审校稿移入 <code>04-review/</code> 目录等待人工终审。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/TGF0wLSNFiL6A8kDHZAcXL2bnGd" target="_blank" rel="noreferrer">《用Grok Bot搭建自媒体团队：保姆级教程｜Adrian Punk》</a></p><h3 id="配图与视觉呈现-代码化建站与素材拼装" tabindex="-1">配图与视觉呈现：代码化建站与素材拼装 <a class="header-anchor" href="#配图与视觉呈现-代码化建站与素材拼装" aria-label="Permalink to &quot;配图与视觉呈现：代码化建站与素材拼装&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/0xlangeai/status/2109115005069341175" target="_blank" rel="noreferrer">把自己的推文做成个人画像网站, 用 Grok Bot 从分析特点到上线分享保姆级教程</a><br> 作者：<a href="https://x.com/0xlangeai" target="_blank" rel="noreferrer">蓝哥AI @0xlangeai</a></p></blockquote><p><img src="`+e+'" alt="把自己的推文做成个人画像网站,  用 Grok Bot 从分析特点到上线分享保姆级教程" loading="lazy" decoding="async"></p><p><img src="'+t+`" alt="把自己的推文做成个人画像网站,  用 Grok Bot 从分析特点到上线分享保姆级教程" loading="lazy" decoding="async"></p><p>自媒体配图别让 AI 随手画概念图，满屏塑料感。实操通常走两条实在路径：</p><p><strong>路径一：把推文做成个人画像网站（蓝哥AI 方案）</strong> 在「推文画像网站」群里由 4 个 Bot 接力，中间文件沉淀在 <code>/workspace/tweet-portrait/</code>：</p><ol><li>推文整理员抓取历史推文，画像分析师提炼表达习惯与反差。</li><li>网站设计师出视觉布局方案，网站工程师写前端代码并做手机端适配。</li></ol><p>前两个角色按顺序执行提示词：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【推文整理员任务】</span></span>
<span class="line"><span>确认我自己已绑定的 X 账号身份，读取最近 90 天内最多 100 条本人内容，包括原创、带有本人评论的引用推文和本人回复，排除纯转发。</span></span>
<span class="line"><span>建立一个名为 tweet-portrait 的共用项目目录，将素材保存为 tweets.md。每条保留正文、日期、链接和内容类型，并注明实际读取范围、数量与缺失情况。</span></span>
<span class="line"><span>完成后返回账号名称、项目目录及素材文件的完整路径。无法访问时告诉我具体原因，不补造内容。</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【个人画像分析师任务】</span></span>
<span class="line"><span>读取共用项目目录中的 tweets.md，提炼最有辨识度的 3—5 个特点，覆盖关注主题、表达风格、语言习惯、典型观点或有趣反差。</span></span>
<span class="line"><span>每个特点附 1—2 条真实推文依据，保留摘录、日期和链接，区分观察与推测。不要写通用赞美或没有依据的人格结论。</span></span>
<span class="line"><span>保存为 profile.md，在群里汇报最有意思的特点和需要我确认的判断，完成后等我检查。</span></span></code></pre></div><p>后两个角色执行设计与代码提示词：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【画像网站设计师任务】</span></span>
<span class="line"><span>读取共用目录中经过我检查的 profile.md，提出两个明显不同的个人画像网站设计方向。</span></span>
<span class="line"><span>分别说明首页如何呈现、包含哪些内容、排版和配色如何对应推文特点。保留原文依据，不生成没有统计基础的百分比或人格分数。</span></span>
<span class="line"><span>先把方向说明发给我，方便选择；需要用图说明时同时提供我可以查看的图片或文件。</span></span>
<span class="line"><span>选定后，把最终页面内容、结构、视觉和手机端安排保存为共用目录中的 design.md。</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【画像网站工程师任务】</span></span>
<span class="line"><span>读取共用项目目录中的 profile.md 和 design.md，按选定方案创建可以运行的个人画像网站，文件放在项目目录内。</span></span>
<span class="line"><span>保留推文依据和原文链接。打开页面检查桌面端与手机端，修复排版、内容和链接问题。</span></span>
<span class="line"><span>返回我能打开的预览及实际截图，先等待我检查，再进行发布。</span></span></code></pre></div><p>本地预览检查首屏文案、卡片间距和手机端显示，确认后让工程师打包，<strong>推送到 Vercel 或 Cloudflare Pages 上线</strong>。</p><p><strong>路径二：参数化拼装与音视频切片（铁柱 / 官方工具方案）</strong></p><ul><li>角色与穿搭：用游戏数据纸娃娃系统，Bot 分析参数后调用第三方 API 拼接。</li><li>视频切片：使用官方 Clip Bot 模板，直接输入音视频长链接，自动转出带时间戳文稿并截取重点片段。</li></ul><p><strong>验收标准</strong></p><ul><li>本地预览排版工整，手机端自适应正常。</li><li>引用推文全部带原链接且可跳转。</li><li>页面紧扣真实表达，不虚构履历。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/BgFKwIqQSiGyWzk1r5rcsTcTnFh" target="_blank" rel="noreferrer">《把自己的推文做成个人画像网站, 用 Grok Bot 从分析特点到上线分享保姆级教程》</a>；<a href="https://jcng5q8n0f3z.feishu.cn/wiki/SMztw0FlBilqx5k1tXzc9kFjndb" target="_blank" rel="noreferrer">《铁柱推文合集③：实战玩法与案例》</a></p><h3 id="分发、复盘与审核-人闸把关与错位流转" tabindex="-1">分发、复盘与审核：人闸把关与错位流转 <a class="header-anchor" href="#分发、复盘与审核-人闸把关与错位流转" aria-label="Permalink to &quot;分发、复盘与审核：人闸把关与错位流转&quot;">​</a></h3><p>新手常追求全自动无人值守，这很容易导致封号。<strong>严禁在云电脑虚拟机内用浏览器发帖</strong>，平台风控能识别虚拟机指纹。发帖必须设绝对人闸，由博主本人在本地真实设备上手动发布。</p><p>团队协作采用时间错位法，不必整天守着屏幕：</p><ul><li>选题池按周定：每周花 30 分钟在表格里挑候选卡片，勾选通过。</li><li>初稿按日看：博主每天花 10 分钟看 <code>04-review/</code> 里的稿件，补上一段个人体会。</li><li>状态看板流转：在表格里跑通待审、写作中、已定稿和已发布状态。</li></ul><p>内容发出后安排数据复盘师每周只读分析，严禁代发或互动：</p><details class="details custom-block"><summary>分发、复盘与审核：人闸把关与错位流转</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是我的 X 数据复盘师（Analyst）。唯一职责是分析用户自己的 X 内容质量、帖子表现和可执行的改进方向；只读，不代表用户进行任何互动或账号操作。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【允许使用】</span></span>
<span class="line"><span>- 用户在任务中明确指定的个人 X 主页，以及该账号公开可见的帖子。</span></span>
<span class="line"><span>- 用户主动提供或授权查看的 X Analytics 页面、CSV 导出和截图。</span></span>
<span class="line"><span>- /workspace/content-team/03-drafts/、/04-review/、/05-published/ 与 /06-analysis/。</span></span>
<span class="line"><span>- 如页面要求登录、密码、验证码、2FA 或 passkey，立即停下并请用户接管；不得索取或记录凭据。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【绝对禁止】</span></span>
<span class="line"><span>- 不得发帖、改帖、删帖、点赞、转发、收藏、关注、取关、评论或私信。</span></span>
<span class="line"><span>- 不得修改头像、简介、账号设置、隐私设置或权限。</span></span>
<span class="line"><span>- 不得读取、复制或分析私信与非本任务所需的个人数据。</span></span>
<span class="line"><span>- 不得把浏览量相关性写成因果，不得补全缺失指标。</span></span>
<span class="line"><span>- 不得执行本机命令，不得访问本机文件。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【固定交付】</span></span>
<span class="line"><span>每周写入 /workspace/content-team/06-analysis/weekly-review-YYYY-WW.md，包含数据来源、时间范围、样本量、表现最好与最差的帖子、内容质量诊断、3 条改进建议、2 个下周实验、数据缺口。需要在 /workspace/content-team/05-published/ 留存所用 CSV 或截图的文件名，不复制账号凭据。</span></span></code></pre></div></details><p>单次针对特定时段复盘直接发指令：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>只读分析我明确指定的个人 X 主页【主页地址】，时间范围为【开始日期—结束日期】。数据来源为【公开主页 / X Analytics / CSV / 截图】。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先列出数据范围和缺失字段，再按主题、内容形式、长度、发布时间和开头类型做对比。给 3 条有具体帖子或指标支撑的改进建议，并设计 2 个一次只改变一个变量的下周实验。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止发帖、改帖、删帖、点赞、转发、收藏、关注、取关、评论、私信和修改账号设置。遇到登录、验证码、2FA、passkey 或扩大权限时立即停下，等我接管。完成后写入 06-analysis，并只回复文件路径、覆盖帖子数和缺失数据。</span></span></code></pre></div><p><strong>验收标准</strong></p><ul><li>真人本地手动发布，零风控封号风险。</li><li>复盘数据能回溯到原始导出文件。</li><li><strong>样本量少于 10 条时不妄下结论</strong>。</li><li>下周规划包含 2 个单变量对照实验（例如对比不同字数对互动率的影响）。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/TGF0wLSNFiL6A8kDHZAcXL2bnGd" target="_blank" rel="noreferrer">《用Grok Bot搭建自媒体团队：保姆级教程｜Adrian Punk》</a>；<a href="https://jcng5q8n0f3z.feishu.cn/wiki/FzlswUo4GiBJYuk9xO7cyIIWnRf" target="_blank" rel="noreferrer">《做自媒体怎么用好 Grok bot｜Kin》</a></p><h2 id="典型实战案例深度拆解" tabindex="-1">典型实战案例深度拆解 <a class="header-anchor" href="#典型实战案例深度拆解" aria-label="Permalink to &quot;典型实战案例深度拆解&quot;">​</a></h2><p><img src="`+f+'" alt="典型实战案例深度拆解" width="1600" height="1013" loading="lazy" decoding="async"></p><h3 id="案例-1-adrian-punk-的五人闭环自媒体团队" tabindex="-1">案例 1：Adrian Punk 的五人闭环自媒体团队 <a class="header-anchor" href="#案例-1-adrian-punk-的五人闭环自媒体团队" aria-label="Permalink to &quot;案例 1：Adrian Punk 的五人闭环自媒体团队&quot;">​</a></h3><p>Adrian Punk（@AdrianPunk115）在桌面端搭建 5 人长期角色团队，跑通一手资料抓取、选题、撰写、审校到复盘的闭环。</p><ol><li><strong>权限前置收紧</strong>：在客户端设置中将「在这台电脑上执行」设为「从不允许」，提示词明文禁止私自发帖、代输密码与调用连接器。</li><li><strong>搭建文件路径</strong>：在云电脑建立 <code>/workspace/content-team/</code> 及其 7 个子目录，在 <code>00-profile/voice.md</code> 放入账号风格、代表作与禁用词。</li><li><strong>专职分工</strong>：建立情报侦察员、选题策划师、内容主笔、事实编辑与数据复盘师，严格限定各岗位输入输出目录。</li><li><strong>规约交接</strong>：在「自媒体内容团队」群发启动指令，上游产出写成 Markdown 供下游读取，<strong>未获人工批准不得越级推进</strong>。</li></ol><p>注意：5 个 Bot 共享云电脑且无沙箱隔离，权限必须依赖明确的角色边界；<strong>事实编辑必须独立比对原始链接</strong>，过滤主笔编造的数字与公关腔。</p><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/TGF0wLSNFiL6A8kDHZAcXL2bnGd" target="_blank" rel="noreferrer">《用Grok Bot搭建自媒体团队：保姆级教程｜Adrian Punk》</a></p><h3 id="案例-2-kin-的推文与视频双轮爆款库" tabindex="-1">案例 2：Kin 的推文与视频双轮爆款库 <a class="header-anchor" href="#案例-2-kin-的推文与视频双轮爆款库" aria-label="Permalink to &quot;案例 2：Kin 的推文与视频双轮爆款库&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/KinGao476942/status/2096232745538334913" target="_blank" rel="noreferrer">工程师如何用好 Grok bot?</a><br> 作者：<a href="https://x.com/KinGao476942" target="_blank" rel="noreferrer">Kin @KinGao476942</a></p></blockquote><p><img src="'+i+'" alt="工程师如何用好 Grok bot?" loading="lazy" decoding="async"></p><p><img src="'+o+'" alt="工程师如何用好 Grok bot?" loading="lazy" decoding="async"></p><p>Kin（@KinGao476942，SpaceXAI 中国区大使）10 多天在推特涨粉 2000+，操盘过百万粉视频号，搭建起推特运营 Bot 与「小邓Talk」爆款选题库。</p><ol><li><strong>立身份卡</strong>：写明定位、对标账号与禁碰领域，禁止自动发推。<strong>找不到数据必须写“未找到”，严禁估算编造</strong>。</li><li><strong>真实数据反哺</strong>：拉取历史 100 多条帖子，测出 200 到 500 字阅读中位数更高、带编号步骤点赞显著更高。</li><li><strong>六字段选题库</strong>：建立含原帖永久链、抓取时间、真实数据、粉丝分层、社区分层与动机拆解的表格，同步至 Notion 看板做过筛。</li><li><strong>拆解结构</strong>：按 HKRR（快乐、知识、共鸣、节奏感）与潘乱三种动机拆解爆款，抄结构不抄内容。</li></ol><p>注意：起号阶段高频产出优于过度打磨，写完检查主语是否切中读者利益。</p><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/FzlswUo4GiBJYuk9xO7cyIIWnRf" target="_blank" rel="noreferrer">《做自媒体怎么用好 Grok bot｜Kin》</a></p><h3 id="案例-3-蓝哥ai-的推文个人画像网站" tabindex="-1">案例 3：蓝哥AI 的推文个人画像网站 <a class="header-anchor" href="#案例-3-蓝哥ai-的推文个人画像网站" aria-label="Permalink to &quot;案例 3：蓝哥AI 的推文个人画像网站&quot;">​</a></h3><p>蓝哥AI（@0xlangeai）抓取已绑定的 X 历史推文，提炼个人风格与反差，自动化上线了个人画像展示网站。</p><ol><li><strong>设立专职 Bot</strong>：在「推文画像网站」项目群配置推文整理员、个人画像分析师、画像网站设计师、画像网站工程师 4 个角色。</li><li><strong>提取与分析</strong>：整理员读取近 90 天内最多 100 条原创、带评论引用及回复存入 <code>tweets.md</code>；分析师提炼 3 到 5 个表达反差与出处，由博主校正。</li><li><strong>设计与部署</strong>：设计师产出 <code>design.md</code>（选用作品集卡片式），<strong>工程师在云电脑编写代码完成双端自检，协助部署到 Vercel 或 Cloudflare Pages</strong>。</li></ol><p>注意：历史动态是现成语料库；<strong>整理、分析、设计、工程每步都需博主确认再进下一阶段</strong>，防止偏差逐级放大。</p><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/BgFKwIqQSiGyWzk1r5rcsTcTnFh" target="_blank" rel="noreferrer">《把自己的推文做成个人画像网站, 用 Grok Bot 从分析特点到上线分享保姆级教程》</a></p><h3 id="案例-4-xilo-的全天候采集与自动化多维表格流" tabindex="-1">案例 4：xilo 的全天候采集与自动化多维表格流 <a class="header-anchor" href="#案例-4-xilo-的全天候采集与自动化多维表格流" aria-label="Permalink to &quot;案例 4：xilo 的全天候采集与自动化多维表格流&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/xilo2991/status/2109613437215293905" target="_blank" rel="noreferrer">零基础搭建全自动化Agent团队，Grok Bot从开通到多AI协作全流程【万字长文】</a><br> 作者：<a href="https://x.com/xilo2991" target="_blank" rel="noreferrer">xilo @xilo2991</a></p></blockquote><p><img src="'+l+'" alt="零基础搭建全自动化Agent团队，Grok Bot从开通到多AI协作全流程【万字长文】" loading="lazy" decoding="async"></p><p><img src="'+p+'" alt="零基础搭建全自动化Agent团队，Grok Bot从开通到多AI协作全流程【万字长文】" loading="lazy" decoding="async"></p><p>xilo（@xilo2991）利用云电脑 24 小时运行特性，搭建全天候爆款采集流水线，实时同步到飞书多维表格。</p><ol><li><strong>确立三要素</strong>：明确渠道、对标账号与关键词、结果存放表格。</li><li><strong>接入表格</strong>：把飞书插件 GitHub 仓库发给 Bot，在云电脑完成配置鉴权，把表格作为协作总线。</li><li><strong>降风控与淘汰</strong>：搜索时控制频次模拟正常浏览；记录搜索次数与爆款概率，<strong>每周复盘自动淘汰无效关键词</strong>。</li><li><strong>访谈理顺</strong>：用单轮追问式访谈提示词发给主 Bot，理顺业务细节后再自动生成配置。</li></ol><p>注意：全自动发帖降级为半自动人工批准，兼顾效率与安全。</p><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/XLjCwUT8AiRWFVktR9wcUFJYnMd" target="_blank" rel="noreferrer">《零基础搭建全自动化Agent团队，Grok Bot从开通到多AI协作全流程【万字长文】》</a></p><h3 id="案例-5-铁柱agi-的单岗专职、多端联动与底座防封" tabindex="-1">案例 5：铁柱AGI 的单岗专职、多端联动与底座防封 <a class="header-anchor" href="#案例-5-铁柱agi-的单岗专职、多端联动与底座防封" aria-label="Permalink to &quot;案例 5：铁柱AGI 的单岗专职、多端联动与底座防封&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/cgnot996/status/2097487429104197688" target="_blank" rel="noreferrer">Grok Bot Webhook + 快捷指令：知识自动入库流水线搭建</a><br> 作者：<a href="https://x.com/cgnot996" target="_blank" rel="noreferrer">铁柱AGI @cgnot996</a></p></blockquote><p><img src="'+r+'" alt="Grok Bot Webhook + 快捷指令：知识自动入库流水线搭建" loading="lazy" decoding="async"></p><p><img src="'+c+'" alt="Grok Bot Webhook + 快捷指令：知识自动入库流水线搭建" loading="lazy" decoding="async"></p><p>铁柱AGI（@cgnot996）系统测试了 Bot 边界，沉淀出防封与容灾方案。</p><ol><li><strong>单岗专职</strong>：拆解成代码巡检、文章捕手、记账归档等单职 Bot，放弃全能 Bot。</li><li><strong>极速录入</strong>：手机端配置快捷指令读取剪贴板，通过 Webhook 直推云电脑内的 Bot 沉淀到表格。</li><li><strong>防封红线</strong>：<strong>虚拟机浏览器模拟发帖极易封号，外发交互必须真人在真实设备执行</strong>。</li><li><strong>灾备恢复</strong>：云电脑重建会清除非持久化环境，写好 Shell 自动恢复脚本，配 Memory Manager Bot 定期备份提示词与配置。</li></ol><p>注意：<strong>关键配置与安装命令必须形成可一键重放的恢复脚本</strong>，云电脑不能当绝对稳定的服务器。</p><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/SMztw0FlBilqx5k1tXzc9kFjndb" target="_blank" rel="noreferrer">《铁柱推文合集③：实战玩法与案例》</a></p><h2 id="容易踩的坑" tabindex="-1">容易踩的坑 <a class="header-anchor" href="#容易踩的坑" aria-label="Permalink to &quot;容易踩的坑&quot;">​</a></h2><ol><li>云电脑发帖会暴露指纹被封，全自动也易乱发。<strong>发帖、点赞与私信必须在真机手动发</strong>。</li><li>角色描述<strong>写死规则：无数据标“未找到”，推论打「推断」</strong>，防假数据入库。</li><li>云电脑重置会清空依赖。<strong>把 Shell 恢复脚本存入持久化目录</strong>备用。</li><li>Routine 任务<strong>仔细核对执行周期</strong>，防误设“仅工作日执行”导致周末断连。</li><li>没做分镜过滤曾致单周额度骤减 40%+，<strong>严禁高频空转轮询，优化触发时机</strong>。</li></ol><p>2026年10月12日起方案：</p><table tabindex="0"><thead><tr><th>方案</th><th>费用</th><th>额度</th><th>含Bot</th></tr></thead><tbody><tr><td>Plus</td><td>$8/月</td><td>-</td><td>否</td></tr><tr><td>Premium</td><td>$30/月或$300/年</td><td>4x</td><td>是</td></tr><tr><td>Super</td><td>$100/月或$1000/年</td><td>15x</td><td>是</td></tr><tr><td>Ultra</td><td>$200/月或$2000/年</td><td>50x</td><td>是</td></tr></tbody></table><h2 id="做完怎么验收" tabindex="-1">做完怎么验收 <a class="header-anchor" href="#做完怎么验收" aria-label="Permalink to &quot;做完怎么验收&quot;">​</a></h2><h3 id="权限与目录" tabindex="-1">权限与目录 <a class="header-anchor" href="#权限与目录" aria-label="Permalink to &quot;权限与目录&quot;">​</a></h3><ol><li>进账户设置「常规 → Agent → 在这台电脑上执行」，<strong>状态必须是「从不允许」</strong>。Bot 严禁自动发帖和支付，不准编造数据。</li><li>检查 <code>/workspace/content-team/</code> 下 7 个子目录，并在 <code>00-profile/voice.md</code> 填好账号定位、范本与禁用词。</li></ol><h3 id="采写与演练" tabindex="-1">采写与演练 <a class="header-anchor" href="#采写与演练" aria-label="Permalink to &quot;采写与演练&quot;">​</a></h3><ol><li>抓 3 条线索，<strong>抽测 2 条链接可访问且有原文支撑</strong>；缺数据标明“未找到公开数据”，不准臆测数字或粉丝量。</li><li>确认 Brief 后出初稿，前两句直接给核心事实，段落保持 2 到 4 句，稿末附事实依据与待确认项，完全规避禁用词。</li><li>审校稿仅核实不加新论点，<strong>没人工指令绝不自动外发</strong>。测试环境跑一次 <code>restore.sh</code>，核对依赖环境正常就绪。</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><h3 id="官方文档" tabindex="-1">官方文档 <a class="header-anchor" href="#官方文档" aria-label="Permalink to &quot;官方文档&quot;">​</a></h3><ul><li><a href="https://cursor.com/cn/help/grok-bot/plans.md" target="_blank" rel="noreferrer">方案与计费</a></li><li><a href="https://cursor.com/cn/docs/grok-bot/teams.md" target="_blank" rel="noreferrer">Bot 团队与协作</a></li><li><a href="https://cursor.com/cn/docs/grok-bot/computers.md" target="_blank" rel="noreferrer">云电脑环境与配置</a></li><li><a href="https://cursor.com/cn/help/grok-bot/group-chats.md" target="_blank" rel="noreferrer">群聊协作</a></li><li><a href="https://cursor.com/cn/help/grok-bot/routines.md" target="_blank" rel="noreferrer">例行任务与自动化</a></li></ul><h3 id="社区实战来源" tabindex="-1">社区实战来源 <a class="header-anchor" href="#社区实战来源" aria-label="Permalink to &quot;社区实战来源&quot;">​</a></h3><ul><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/TGF0wLSNFiL6A8kDHZAcXL2bnGd" target="_blank" rel="noreferrer">《用Grok Bot搭建自媒体团队：保姆级教程｜Adrian Punk》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/FzlswUo4GiBJYuk9xO7cyIIWnRf" target="_blank" rel="noreferrer">《做自媒体怎么用好 Grok bot｜Kin》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/BgFKwIqQSiGyWzk1r5rcsTcTnFh" target="_blank" rel="noreferrer">《把自己的推文做成个人画像网站, 用 Grok Bot 从分析特点到上线分享保姆级教程》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/XLjCwUT8AiRWFVktR9wcUFJYnMd" target="_blank" rel="noreferrer">《零基础搭建全自动化Agent团队，Grok Bot从开通到多AI协作全流程【万字长文】》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/SMztw0FlBilqx5k1tXzc9kFjndb" target="_blank" rel="noreferrer">《铁柱推文合集③：实战玩法与案例》</a></li></ul>',130)])])}const F=d(m,[["render",x]]);export{I as __pageData,F as default};
